"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

PAGE_SIZE = 100
MAX_ATTEMPTS = 10

QUERY = """query Settlements($first: Int, $after: String) {
  settlements(first: $first, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}"""


def _post(url, query, variables):
    body = json.dumps({"query": query, "variables": variables}).encode()
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=10) as resp:
        return json.load(resp)


def graphql(url, query, variables=None):
    """POST one query, retrying identical requests when rate limited."""
    variables = variables or {}
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            result = _post(url, query, variables)
            break
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            retry_after = exc.headers.get("Retry-After")
            try:
                delay = max(0.0, float(retry_after))
            except (TypeError, ValueError):
                delay = 1.0
            if attempt == MAX_ATTEMPTS:
                raise
            time.sleep(delay)
    if result.get("errors"):
        raise RuntimeError(result["errors"])
    return result["data"]


def fetch_settlements(url):
    """Traverse all pages, keyed by id with the last delivered version winning."""
    by_id = {}
    after = None
    restarted = False
    while True:
        try:
            data = graphql(url, QUERY, {"first": PAGE_SIZE, "after": after})
        except RuntimeError:
            # A malformed or expired cursor is a GraphQL error: start over
            # without `after`. Deduping by id makes the replay harmless.
            if after is not None and not restarted:
                after = None
                restarted = True
                continue
            raise
        connection = data["settlements"]
        for settlement in connection["nodes"]:
            by_id[settlement["id"]] = settlement
        page_info = connection["pageInfo"]
        if not page_info["hasNextPage"]:
            break
        # An empty or short page can still have more pages behind it.
        after = page_info["endCursor"]
    return list(by_id.values())


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    settlements = fetch_settlements(f"{args.base_url.rstrip('/')}/v2/graphql")
    with open(args.out, "w") as f:
        for s in settlements:
            f.write(json.dumps(s) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

